    id: "agency:content/templates/delivery/examples/exampleco-runbook",
    property: "agency",
    title: "Workflow Runbook",
    description: "Workflow Runbook",
    section: "content",
    path: "content/templates/delivery/examples/exampleco-runbook.md",
